module QspiSlave (
  input  wire          io_sclk,
  input  wire          io_cs_n,
  input  wire [3:0]    io_data_in,
  output wire [3:0]    io_data_out,
  output wire          io_data_oe,
  input  wire          io_txEnable,
  output wire          io_rx_valid,
  input  wire          io_rx_ready,
  output wire [7:0]    io_rx_payload,
  input  wire          io_tx_valid,
  output wire          io_tx_ready,
  input  wire [7:0]    io_tx_payload,
  input  wire          clk,
  input  wire          rst_n
);

  reg                 txFifo_io_pop_ready;
  wire                io_sclk_buffercc_io_dataOut;
  wire                io_cs_n_buffercc_io_dataOut;
  wire       [3:0]    io_data_in_buffercc_io_dataOut;
  wire                rxFifo_io_push_ready;
  wire                rxFifo_io_pop_valid;
  wire       [7:0]    rxFifo_io_pop_payload;
  wire       [2:0]    rxFifo_io_occupancy;
  wire       [2:0]    rxFifo_io_availability;
  wire                txFifo_io_push_ready;
  wire                txFifo_io_pop_valid;
  wire       [7:0]    txFifo_io_pop_payload;
  wire       [2:0]    txFifo_io_occupancy;
  wire       [2:0]    txFifo_io_availability;
  wire                sclkSync;
  wire                cs_nSync;
  wire       [3:0]    dataSync;
  reg                 sclkPrev;
  reg                 cs_nPrev;
  wire                sclkRise;
  wire                sclkFall;
  wire                cs_nRise;
  wire                cs_nFall;
  wire                isCsActive;
  reg                 rxNibblePhase;
  reg        [3:0]    rxHighNibble;
  reg                 rxByteValid;
  reg        [7:0]    rxByteData;
  wire                when_QspiSlave_l68;
  wire                when_QspiSlave_l72;
  wire                when_QspiSlave_l74;
  reg                 txNibblePhase;
  reg        [7:0]    txHoldingByte;
  reg                 txActive;
  reg        [3:0]    outNibble;
  reg                 outOe;
  wire                when_QspiSlave_l103;
  wire                when_QspiSlave_l107;
  wire                when_QspiSlave_l117;
  wire                when_QspiSlave_l143;

  (* keep_hierarchy = "TRUE" *) BufferCC io_sclk_buffercc (
    .io_dataIn  (io_sclk                    ), //i
    .io_dataOut (io_sclk_buffercc_io_dataOut), //o
    .clk        (clk                        ), //i
    .rst_n      (rst_n                      )  //i
  );
  (* keep_hierarchy = "TRUE" *) BufferCC_1 io_cs_n_buffercc (
    .io_dataIn  (io_cs_n                    ), //i
    .io_dataOut (io_cs_n_buffercc_io_dataOut), //o
    .clk        (clk                        ), //i
    .rst_n      (rst_n                      )  //i
  );
  (* keep_hierarchy = "TRUE" *) BufferCC_2 io_data_in_buffercc (
    .io_dataIn  (io_data_in[3:0]                    ), //i
    .io_dataOut (io_data_in_buffercc_io_dataOut[3:0]), //o
    .clk        (clk                                ), //i
    .rst_n      (rst_n                              )  //i
  );
  StreamFifo rxFifo (
    .io_push_valid   (rxByteValid                ), //i
    .io_push_ready   (rxFifo_io_push_ready       ), //o
    .io_push_payload (rxByteData[7:0]            ), //i
    .io_pop_valid    (rxFifo_io_pop_valid        ), //o
    .io_pop_ready    (io_rx_ready                ), //i
    .io_pop_payload  (rxFifo_io_pop_payload[7:0] ), //o
    .io_flush        (1'b0                       ), //i
    .io_occupancy    (rxFifo_io_occupancy[2:0]   ), //o
    .io_availability (rxFifo_io_availability[2:0]), //o
    .clk             (clk                        ), //i
    .rst_n           (rst_n                      )  //i
  );
  StreamFifo txFifo (
    .io_push_valid   (io_tx_valid                ), //i
    .io_push_ready   (txFifo_io_push_ready       ), //o
    .io_push_payload (io_tx_payload[7:0]         ), //i
    .io_pop_valid    (txFifo_io_pop_valid        ), //o
    .io_pop_ready    (txFifo_io_pop_ready        ), //i
    .io_pop_payload  (txFifo_io_pop_payload[7:0] ), //o
    .io_flush        (1'b0                       ), //i
    .io_occupancy    (txFifo_io_occupancy[2:0]   ), //o
    .io_availability (txFifo_io_availability[2:0]), //o
    .clk             (clk                        ), //i
    .rst_n           (rst_n                      )  //i
  );
  assign sclkSync = io_sclk_buffercc_io_dataOut;
  assign cs_nSync = io_cs_n_buffercc_io_dataOut;
  assign dataSync = io_data_in_buffercc_io_dataOut;
  assign sclkRise = (sclkSync && (! sclkPrev));
  assign sclkFall = ((! sclkSync) && sclkPrev);
  assign cs_nRise = (cs_nSync && (! cs_nPrev));
  assign cs_nFall = ((! cs_nSync) && cs_nPrev);
  assign isCsActive = (! cs_nSync);
  assign io_rx_valid = rxFifo_io_pop_valid;
  assign io_rx_payload = rxFifo_io_pop_payload;
  assign when_QspiSlave_l68 = (rxByteValid && rxFifo_io_push_ready);
  assign when_QspiSlave_l72 = (isCsActive && (! io_txEnable));
  assign when_QspiSlave_l74 = (! rxNibblePhase);
  assign io_tx_ready = txFifo_io_push_ready;
  always @(*) begin
    txFifo_io_pop_ready = 1'b0;
    if(when_QspiSlave_l103) begin
      if(when_QspiSlave_l107) begin
        if(txFifo_io_pop_valid) begin
          txFifo_io_pop_ready = 1'b1;
        end
      end else begin
        if(sclkFall) begin
          if(!when_QspiSlave_l117) begin
            if(txFifo_io_pop_valid) begin
              txFifo_io_pop_ready = 1'b1;
            end
          end
        end
      end
    end
  end

  assign when_QspiSlave_l103 = (isCsActive && io_txEnable);
  assign when_QspiSlave_l107 = (! txActive);
  assign when_QspiSlave_l117 = (! txNibblePhase);
  assign when_QspiSlave_l143 = (! isCsActive);
  assign io_data_out = outNibble;
  assign io_data_oe = outOe;
  always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
      sclkPrev <= 1'b0;
      cs_nPrev <= 1'b1;
      rxNibblePhase <= 1'b0;
      rxByteValid <= 1'b0;
      txNibblePhase <= 1'b0;
      txActive <= 1'b0;
      outNibble <= 4'b0000;
      outOe <= 1'b0;
    end else begin
      sclkPrev <= sclkSync;
      cs_nPrev <= cs_nSync;
      if(when_QspiSlave_l68) begin
        rxByteValid <= 1'b0;
      end
      if(when_QspiSlave_l72) begin
        if(sclkRise) begin
          if(when_QspiSlave_l74) begin
            rxNibblePhase <= 1'b1;
          end else begin
            rxByteValid <= 1'b1;
            rxNibblePhase <= 1'b0;
          end
        end
      end
      if(when_QspiSlave_l103) begin
        outOe <= 1'b1;
        if(when_QspiSlave_l107) begin
          if(txFifo_io_pop_valid) begin
            txActive <= 1'b1;
            txNibblePhase <= 1'b0;
            outNibble <= txFifo_io_pop_payload[7 : 4];
          end
        end else begin
          if(sclkFall) begin
            if(when_QspiSlave_l117) begin
              outNibble <= txHoldingByte[3 : 0];
              txNibblePhase <= 1'b1;
            end else begin
              txNibblePhase <= 1'b0;
              if(txFifo_io_pop_valid) begin
                outNibble <= txFifo_io_pop_payload[7 : 4];
              end else begin
                txActive <= 1'b0;
                outNibble <= 4'b0000;
              end
            end
          end
        end
      end else begin
        outOe <= 1'b0;
        txActive <= 1'b0;
        txNibblePhase <= 1'b0;
        outNibble <= 4'b0000;
      end
      if(when_QspiSlave_l143) begin
        rxNibblePhase <= 1'b0;
        txNibblePhase <= 1'b0;
        txActive <= 1'b0;
        outOe <= 1'b0;
      end
    end
  end

  always @(posedge clk) begin
    if(when_QspiSlave_l72) begin
      if(sclkRise) begin
        if(when_QspiSlave_l74) begin
          rxHighNibble <= dataSync;
        end else begin
          rxByteData <= {rxHighNibble,dataSync};
        end
      end
    end
    if(when_QspiSlave_l103) begin
      if(when_QspiSlave_l107) begin
        if(txFifo_io_pop_valid) begin
          txHoldingByte <= txFifo_io_pop_payload;
        end
      end else begin
        if(sclkFall) begin
          if(!when_QspiSlave_l117) begin
            if(txFifo_io_pop_valid) begin
              txHoldingByte <= txFifo_io_pop_payload;
            end
          end
        end
      end
    end
  end


endmodule

